"""Independently authored OOXML controls for first-cell paragraph keepNext."""
from zipfile import ZipFile,ZIP_DEFLATED
from pathlib import Path
DEST = Path(__file__).resolve().parents[1] / 'tests/fixtures/table-row-keep-next'
DEST.mkdir(exist_ok=True)
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
for flag in ['none','first','second','first-start','first-end']:
 def p(text='',keep=False,height=12):return f'<w:p><w:pPr>{"<w:keepNext/>" if keep else ""}<w:spacing w:before="0" w:after="0" w:line="{height*20}" w:lineRule="exact"/></w:pPr><w:r><w:t>{text}</w:t></w:r></w:p>'
 def cell(text,keep=False):return '<w:tc><w:tcPr><w:tcW w:w="2400" w:type="dxa"/></w:tcPr>'+p(text,keep)+'</w:tc>'
 doc=f'<w:document xmlns:w="{W}"><w:body>'+p('Before',height=180)+'<w:tbl><w:tblPr><w:tblW w:w="4800" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:tblCellMar>'+''.join(f'<w:{s} w:w="0" w:type="dxa"/>' for s in ['top','left','bottom','right'])+'</w:tblCellMar></w:tblPr><w:tblGrid><w:gridCol w:w="2400"/><w:gridCol w:w="2400"/></w:tblGrid><w:tr><w:trPr><w:trHeight w:val="400"/></w:trPr>'+cell('Row one')+cell('Neighbor one')+'</w:tr><w:tr><w:trPr><w:trHeight w:val="600"/></w:trPr>'+(('<w:tc><w:tcPr><w:tcW w:w="2400" w:type="dxa"/></w:tcPr>'+p('A',flag=='first-start')+p('B',flag=='first-end')+'</w:tc>') if flag.startswith('first-') else cell('',flag=='first'))+cell('Final label',flag=='second')+'</w:tr></w:tbl>'+p('Tail')+'<w:sectPr><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600" w:header="0" w:footer="0" w:gutter="0"/></w:sectPr></w:body></w:document>'
 parts={'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>', '_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>', 'word/_rels/document.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>', 'word/document.xml':doc,'word/styles.xml':f'<w:styles xmlns:w="{W}"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="24"/></w:rPr></w:rPrDefault></w:docDefaults></w:styles>'}
 with ZipFile(DEST / f'{flag}.docx','w',ZIP_DEFLATED) as z:
  for name,xml in parts.items():z.writestr(name,xml)
